`timescale 1ns/1ps
module tb_mlkem_prf;reg clk=0,rst_n=0,start=0,out_ready=0;reg[255:0]seed;reg[7:0]nonce;reg[1:0]eta;wire ready,out_valid;wire[31:0]out_data;wire[3:0]out_keep;wire out_last,busy,done,error;reg[2047:0]expected;integer fd,rc,ieta,inonce,vectors,bytes,pos,n,k,watchdog;reg[1023:0]path;always #5 clk=~clk;
mlkem_prf dut(.clk(clk),.rst_n(rst_n),.start(start),.ready(ready),.seed(seed),.nonce(nonce),.eta(eta),.out_valid(out_valid),.out_ready(out_ready),.out_data(out_data),.out_keep(out_keep),.out_last(out_last),.busy(busy),.done(done),.error(error));
task reset;begin @(negedge clk);rst_n=0;start=0;out_ready=0;@(posedge clk);#1;@(negedge clk);rst_n=1;end endtask
initial begin vectors=0;bytes=0;reset();if(!$value$plusargs("VECTORS=%s",path))$fatal(1,"vectors");fd=$fopen(path,"r");while(!$feof(fd))begin rc=$fscanf(fd,"%d %d %h %h\n",ieta,inonce,seed,expected);if(rc==4)begin while(!ready)@(posedge clk);@(negedge clk);eta=ieta;nonce=inonce;start=1;@(posedge clk);#1;@(negedge clk);start=0;pos=0;watchdog=0;while(pos<64*ieta&&watchdog<30000)begin @(negedge clk);out_ready=((watchdog+vectors)%5)!=0;@(posedge clk);watchdog=watchdog+1;if(out_valid&&out_ready)begin n=(out_keep==1)?1:(out_keep==3)?2:(out_keep==7)?3:4;for(k=0;k<n;k=k+1)begin bytes=bytes+1;if(out_data[8*k+:8]!==expected[8*(pos+k)+:8])$fatal(1,"prf vector=%0d byte=%0d",vectors,pos+k);end pos=pos+n;if(out_last!==(pos==64*ieta))$fatal(1,"last");end end if(watchdog>=30000)$fatal(1,"watchdog");@(negedge clk);out_ready=0;@(posedge clk);#1;if(done)$fatal(1,"done width");if(error)$fatal(1,"error");vectors=vectors+1;end end $fclose(fd);if(vectors!=128)$fatal(1,"count");reset();@(negedge clk);eta=1;start=1;@(posedge clk);#1;@(negedge clk);start=0;if(!error)$fatal(1,"bad eta");reset();@(negedge clk);eta=2;start=1;@(posedge clk);#1;@(negedge clk);start=1;@(posedge clk);#1;if(!error)$fatal(1,"busy start");$display("PASS tb_mlkem_prf vectors=%0d bytes=%0d eta2_bytes=8192 eta3_bytes=12288",vectors,bytes);$finish;end
endmodule
